def groups():
    result = []
    for line in CATALOGUE.strip().splitlines():
        ident, module, title, actors, pre, steps, expected, variants = line.split('|')
        if variants == 'CATEGORY_MATRIX':
            variants = [f'{cat} / {sub}' for cat, subs in CATEGORIES.items() for sub in subs]
            variants += ['Peripheral / mouse', 'Peripheral / keyboard', 'Peripheral / monitor', 'Peripheral / controller']
        elif variants == 'ADMIN_RECORD_MATRIX':
            variants = ADMIN_RECORDS
        elif variants == 'RECOGNITION_MATRIX':
            variants = [f'{cat} / {sub} / {view}' for cat, subs in CATEGORIES.items()
                for sub in subs for view in ['whole and alternate views', 'detail views', 'unrelated views']]
        else:
            variants = variants.split(';')
        result.append(dict(id=ident, priority=ident[:2], module=MODULES[module], title=title,
            accounts=actors, preconditions=pre, steps=steps.split(';'), expectedResult=expected,
            variants=variants, regressionReferences=SUITE_REFERENCES[module]))
    return result

def cases():
    return [dict(id=f"{g['id']}-{i:02d}", groupId=g['id'], priority=g['priority'], module=g['module'],
        title=f"{g['title']} — {variant}", accounts=g['accounts'], preconditions=g['preconditions'],
        steps=[f'Use a fresh dedicated record for variant: {variant}.', *g['steps']],
        expectedResult=g['expectedResult'], regressionReferences=g['regressionReferences'])
        for g in groups() for i, variant in enumerate(g['variants'], 1)]
